const PAGE_HTML = "<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><script>window.DOPE_API = \"/api\";</script></head><body><title>DOPE レジ</title>\n<meta name=\"claude:viewport-fit-sides\" content=\"cover\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Dela+Gothic+One&family=JetBrains+Mono:wght@500;700&family=Zen+Kaku+Gothic+New:wght@400;500;700&display=swap\">\n<style>\n/* Layout: a 2×2 product board (paid row / ticket row, ticket tiles cut like a stub) beside a receipt-style cart; summary and history live in tabs */\n:root{\n  --bg:#F1F2F6; --surface:#FFFFFF; --surface-2:#E7E9F0; --ink:#15161C; --muted:#5A5E6D; --line:#D5D8E2;\n  --accent:#2537E6; --accent-ink:#FFFFFF; --accent-soft:#E3E6FF;\n  --ticket:#C41C61; --ticket-ink:#FFFFFF; --ticket-soft:#FBE3ED;\n  --vanilla-bg:#F6ECB6; --vanilla-ink:#574404;\n  --ok:#157046; --warn:#975000; --danger:#C2122B; --danger-ink:#FFFFFF;\n  --shadow:0 1px 2px rgba(20,22,40,.06),0 6px 18px rgba(20,22,40,.06);\n  --f-display:\"Dela Gothic One\",\"Hiragino Sans\",\"Yu Gothic\",sans-serif;\n  --f-body:\"Zen Kaku Gothic New\",\"Hiragino Sans\",\"Hiragino Kaku Gothic ProN\",\"Yu Gothic\",\"Meiryo\",sans-serif;\n  --f-num:\"JetBrains Mono\",ui-monospace,\"SFMono-Regular\",Menlo,Consolas,monospace;\n}\n@media (prefers-color-scheme: dark){\n  :root:not([data-theme=\"light\"]){\n    --bg:#0E0F14; --surface:#181A22; --surface-2:#232631; --ink:#EEF0F6; --muted:#9BA0B1; --line:#2D303C;\n    --accent:#7684FF; --accent-ink:#0A0C1A; --accent-soft:#242B5E;\n    --ticket:#FF609E; --ticket-ink:#1B0611; --ticket-soft:#46162D;\n    --vanilla-bg:#3C3414; --vanilla-ink:#F3E39C;\n    --ok:#4DC48B; --warn:#F0A24E; --danger:#FF6B80; --danger-ink:#1E0509;\n    --shadow:0 1px 2px rgba(0,0,0,.4),0 6px 18px rgba(0,0,0,.3);\n    color-scheme:dark;\n  }\n}\n:root[data-theme=\"dark\"]{\n  --bg:#0E0F14; --surface:#181A22; --surface-2:#232631; --ink:#EEF0F6; --muted:#9BA0B1; --line:#2D303C;\n  --accent:#7684FF; --accent-ink:#0A0C1A; --accent-soft:#242B5E;\n  --ticket:#FF609E; --ticket-ink:#1B0611; --ticket-soft:#46162D;\n  --vanilla-bg:#3C3414; --vanilla-ink:#F3E39C;\n  --ok:#4DC48B; --warn:#F0A24E; --danger:#FF6B80; --danger-ink:#1E0509;\n  --shadow:0 1px 2px rgba(0,0,0,.4),0 6px 18px rgba(0,0,0,.3);\n  color-scheme:dark;\n}\n*{box-sizing:border-box}\n[hidden]{display:none!important}\nbody{background:var(--bg);color:var(--ink);font-family:var(--f-body);font-size:15px;line-height:1.5;-webkit-text-size-adjust:100%}\nbutton{font:inherit;color:inherit;cursor:pointer;touch-action:manipulation;-webkit-tap-highlight-color:transparent}\nbutton:disabled{cursor:default}\n:focus-visible{outline:3px solid var(--accent);outline-offset:2px}\n.app{max-width:1100px;margin:0 auto;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));padding-block:10px 32px}\n\n/* header */\n.top{display:flex;align-items:center;flex-wrap:wrap;gap:10px 14px;padding-block:6px 14px}\n.brand{display:flex;align-items:baseline;gap:8px;margin:0;font-weight:400}\n.brand b{font-family:var(--f-display);font-weight:400;font-size:28px;line-height:1;letter-spacing:.02em}\n.brand span{font-weight:700;font-size:15px;letter-spacing:.1em}\n.status{display:inline-flex;align-items:center;gap:6px;font-size:12px;font-weight:700;padding:4px 10px;border-radius:999px;background:var(--surface);border:1px solid var(--line);color:var(--muted);white-space:nowrap}\n.status::before{content:\"\";width:8px;height:8px;border-radius:50%;background:currentColor}\n.status[data-s=\"shared\"]{color:var(--ok)}\n.status[data-s=\"local\"]{color:var(--warn)}\n.status[data-s=\"error\"],.status[data-s=\"readonly\"]{color:var(--danger)}\n.tabs{margin-left:auto;display:flex;gap:2px;padding:4px;border-radius:12px;background:var(--surface-2)}\n.tabs a{padding:8px 16px;border-radius:9px;color:var(--muted);font-weight:700;font-size:14px;text-decoration:none;text-align:center}\n.tabs a[aria-current=\"page\"]{background:var(--surface);color:var(--ink);box-shadow:var(--shadow)}\n\n/* register */\n.register{display:grid;grid-template-columns:minmax(0,1fr);gap:18px}\n.board{display:flex;flex-direction:column;gap:6px;min-width:0}\n.row-head{display:flex;align-items:baseline;justify-content:space-between;flex-wrap:wrap;gap:2px 10px;margin:6px 2px 4px}\n.row-title{font-weight:700;font-size:13px;letter-spacing:.08em;color:var(--accent)}\n.row-head.ticket .row-title{color:var(--ticket)}\n.row-note{font-size:12px;color:var(--muted)}\n.tiles{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}\n.tile{position:relative;display:flex;flex-direction:column;align-items:flex-start;gap:6px;min-height:118px;padding:14px 14px 13px 16px;border-radius:14px;border:2px solid var(--accent);background:var(--surface);text-align:left;transition:transform .08s ease,box-shadow .15s ease}\n.tile:active{transform:scale(.97)}\n.tile-name{font-weight:700;font-size:17px;line-height:1.2}\n.tile-price{margin-top:auto;display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;font-family:var(--f-display);font-size:30px;line-height:1;color:var(--accent)}\n.tile-price s{font-family:var(--f-num);font-size:13px;color:var(--muted)}\n.tile.ticket{border-color:var(--ticket);background:var(--ticket-soft);overflow:hidden}\n.tile.ticket .tile-price{color:var(--ticket)}\n.tile.ticket::before,.tile.ticket::after{content:\"\";position:absolute;top:50%;width:18px;height:18px;margin-top:-9px;border-radius:50%;background:var(--bg);border:2px solid var(--ticket)}\n.tile.ticket::before{left:-11px}\n.tile.ticket::after{right:-11px}\n.tile-count{position:absolute;top:10px;right:12px;min-width:30px;height:30px;padding:0 8px;border-radius:15px;display:grid;place-items:center;background:var(--accent);color:var(--accent-ink);font-family:var(--f-num);font-weight:700;font-size:15px}\n.tile.ticket .tile-count{background:var(--ticket);color:var(--ticket-ink)}\n.tile.has-count{box-shadow:var(--shadow)}\n.chip{display:inline-flex;align-items:center;padding:1px 8px;border-radius:999px;background:var(--vanilla-bg);color:var(--vanilla-ink);font-size:12px;font-weight:700;white-space:nowrap}\n.notice{margin:0;padding:12px 14px;border-radius:12px;background:var(--surface);border:1px solid var(--line);font-size:13px;color:var(--muted)}\n.notice strong{color:var(--ink)}\n\n.cart{display:flex;flex-direction:column;gap:12px;min-width:0}\n.receipt{background:var(--surface);border-radius:16px;box-shadow:var(--shadow);padding:16px;display:flex;flex-direction:column;gap:14px}\n.receipt-head{display:flex;align-items:center;justify-content:space-between}\n.receipt-head h2{margin:0;font-size:14px;letter-spacing:.1em}\n.link-btn{border:0;background:none;padding:6px 4px;color:var(--muted);font-size:13px;font-weight:700;text-decoration:underline;text-underline-offset:3px}\n.lines{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px}\n.line{display:grid;grid-template-columns:minmax(0,1fr) auto auto;align-items:center;gap:10px}\n.line-name{display:flex;flex-wrap:wrap;align-items:center;gap:4px 6px;font-weight:500;min-width:0}\n.tag{font-size:11px;font-weight:700;padding:1px 6px;border-radius:4px;background:var(--accent-soft);color:var(--accent);white-space:nowrap}\n.tag.ticket{background:var(--ticket-soft);color:var(--ticket)}\n.qty{display:flex;align-items:center;gap:2px}\n.qty button{width:36px;height:36px;border-radius:10px;border:1px solid var(--line);background:var(--surface-2);font-size:18px;font-weight:700;line-height:1}\n.qty span{min-width:28px;text-align:center;font-family:var(--f-num);font-weight:700}\n.line-amt{min-width:66px;text-align:right;font-family:var(--f-num);font-weight:500}\n.empty{margin:0;color:var(--muted);font-size:13px}\n.perf{border:0;border-top:2px dashed var(--line);margin:0}\n.pay{display:flex;flex-direction:column;gap:10px}\n.pay-label{font-size:12px;font-weight:700;letter-spacing:.08em;color:var(--muted)}\n.quick{display:flex;flex-wrap:wrap;gap:6px}\n.quick button{flex:1 1 auto;min-height:42px;padding:0 10px;border-radius:10px;border:1px solid var(--line);background:var(--surface-2);font-family:var(--f-num);font-weight:700;font-size:14px}\n.quick button[aria-pressed=\"true\"]{background:var(--ink);color:var(--surface);border-color:var(--ink)}\n.recv{display:flex;align-items:center;gap:6px;padding:0 12px;border-radius:10px;border:1px solid var(--line);background:var(--surface)}\n.recv:focus-within{outline:3px solid var(--accent);outline-offset:1px}\n.recv span{font-family:var(--f-num);color:var(--muted)}\n.recv input{flex:1;min-width:0;height:46px;border:0;background:transparent;color:var(--ink);font-family:var(--f-num);font-size:18px;outline:none}\n.change{display:flex;align-items:baseline;justify-content:space-between;gap:10px}\n.change span{font-size:13px;color:var(--muted)}\n.change strong{font-family:var(--f-display);font-weight:400;font-size:28px;line-height:1.1}\n.change.short strong{color:var(--danger)}\n.change.idle strong{font-family:var(--f-body);font-weight:500;font-size:13px;color:var(--muted)}\n.free-note{margin:0;padding:10px 12px;border-radius:10px;background:var(--ticket-soft);color:var(--ticket);font-weight:700;font-size:13px}\n\n.checkout{display:flex;align-items:center;gap:12px;padding:14px 16px;background:var(--surface);border-radius:16px;box-shadow:var(--shadow)}\n.total{display:flex;flex-direction:column;min-width:0}\n.total-label{font-size:12px;color:var(--muted);font-weight:700;letter-spacing:.08em}\n.total-amt{font-family:var(--f-display);font-size:32px;line-height:1.1;font-variant-numeric:tabular-nums}\n.total-cups{font-size:12px;color:var(--muted)}\n.checkout-btn{margin-left:auto;flex:0 1 230px;min-height:58px;padding:0 18px;border:0;border-radius:14px;background:var(--accent);color:var(--accent-ink);font-weight:700;font-size:18px;letter-spacing:.08em}\n.checkout-btn:disabled{background:var(--surface-2);color:var(--muted)}\n\n/* summary */\n.stack{display:flex;flex-direction:column;gap:14px}\n.chips{display:flex;gap:6px;overflow-x:auto;padding:2px 2px 6px}\n.chips button{flex:0 0 auto;padding:7px 14px;border-radius:999px;border:1px solid var(--line);background:var(--surface);font-weight:700;font-size:13px;white-space:nowrap}\n.chips button[aria-pressed=\"true\"]{background:var(--ink);color:var(--surface);border-color:var(--ink)}\n.kpis{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}\n.kpi{display:flex;flex-direction:column;gap:6px;padding:14px 16px;border-radius:14px;background:var(--surface);box-shadow:var(--shadow);min-width:0}\n.kpi-label{font-size:12px;font-weight:700;letter-spacing:.08em;color:var(--muted)}\n.kpi-val{font-family:var(--f-display);font-size:34px;line-height:1.05;font-variant-numeric:tabular-nums;white-space:nowrap}\n.kpi-sub{font-size:12px;color:var(--muted)}\n.split{display:flex;height:10px;border-radius:5px;overflow:hidden;background:var(--surface-2)}\n.split i{display:block;height:100%}\n.split .p{background:var(--accent)}\n.split .t{background:var(--ticket)}\n.legend{display:flex;flex-wrap:wrap;gap:4px 12px;font-size:12px;color:var(--muted)}\n.legend b{font-family:var(--f-num);color:var(--ink)}\n.dot{display:inline-block;width:8px;height:8px;border-radius:2px;margin-right:4px;vertical-align:1px}\n.dot.p{background:var(--accent)}\n.dot.t{background:var(--ticket)}\n.panel{background:var(--surface);border-radius:14px;box-shadow:var(--shadow);overflow-x:auto}\ntable{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}\nth,td{padding:10px 12px;text-align:right;border-bottom:1px solid var(--line);white-space:nowrap}\nth{font-size:12px;color:var(--muted);font-weight:700;letter-spacing:.06em}\nth:first-child,td:first-child{text-align:left;white-space:normal}\ntd.num{font-family:var(--f-num)}\ntr.group td{font-weight:700}\ntr.group.paid td:first-child{color:var(--accent)}\ntr.group.ticket td:first-child{color:var(--ticket)}\ntr.sub td:first-child{padding-left:24px;color:var(--muted);font-size:14px}\ntr.grand td{font-weight:700;border-bottom:0}\n.facts{display:grid;grid-template-columns:minmax(0,1fr);gap:8px}\n.fact{padding:12px 14px;border-radius:12px;background:var(--surface);border:1px solid var(--line);display:flex;align-items:baseline;justify-content:space-between;gap:10px;min-width:0}\n.fact span{font-size:12px;color:var(--muted)}\n.fact b{font-family:var(--f-num);font-size:18px}\n.actions{display:flex;flex-wrap:wrap;gap:8px}\n.btn{min-height:44px;padding:0 16px;border-radius:12px;border:1px solid var(--line);background:var(--surface);font-weight:700}\n.btn.primary{background:var(--ink);color:var(--surface);border-color:var(--ink)}\n.fine{margin:0;font-size:12px;color:var(--muted)}\n.copy-fallback{width:100%;min-height:150px;padding:12px;border-radius:12px;border:1px solid var(--line);background:var(--surface);color:var(--ink);font-family:var(--f-num);font-size:13px}\n\n/* history */\n.day-head{display:flex;justify-content:space-between;gap:8px;margin:6px 2px 6px;font-size:13px;font-weight:700;color:var(--muted)}\n.day-head b{font-family:var(--f-num);color:var(--ink)}\n.sales{list-style:none;margin:0 0 10px;padding:0;background:var(--surface);border-radius:14px;box-shadow:var(--shadow);overflow:hidden}\n.sale{display:grid;grid-template-columns:auto minmax(0,1fr) auto auto;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid var(--line)}\n.sale:last-child{border-bottom:0}\n.sale-time{font-family:var(--f-num);font-size:13px;color:var(--muted)}\n.sale-items{display:flex;flex-wrap:wrap;gap:4px;min-width:0}\n.sale-amt{text-align:right;font-family:var(--f-num);font-weight:700}\n.sale-amt small{display:block;font-weight:400;font-size:11px;color:var(--muted)}\n.void-btn{min-height:36px;padding:0 10px;border-radius:9px;border:1px solid var(--line);background:var(--surface-2);font-size:12px;font-weight:700;white-space:nowrap}\n.void-btn.armed{background:var(--danger);border-color:var(--danger);color:var(--danger-ink)}\n.sale.voided .sale-items,.sale.voided .sale-amt{opacity:.5;text-decoration:line-through}\n.voided-mark{font-size:11px;font-weight:700;color:var(--danger)}\n\n.btn{display:inline-flex;align-items:center;text-decoration:none;color:var(--ink)}\n.pending-mark{font-size:11px;font-weight:700;color:var(--warn)}\n\n/* login */\n.login{position:fixed;inset:0;z-index:40;display:grid;place-items:center;overflow-y:auto;background:var(--bg);padding:max(16px,env(safe-area-inset-top,0px)) max(16px,env(safe-area-inset-right,0px)) max(16px,env(safe-area-inset-bottom,0px)) max(16px,env(safe-area-inset-left,0px))}\n.login-card{width:100%;max-width:380px;display:flex;flex-direction:column;gap:16px;padding:26px 22px;border-radius:18px;background:var(--surface);box-shadow:var(--shadow)}\n.login-card .brand b{font-size:34px}\n.login-lead{margin:0;color:var(--muted);font-size:14px}\n.field{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:700;letter-spacing:.06em;color:var(--muted)}\n.field input{height:50px;padding:0 14px;border-radius:12px;border:1px solid var(--line);background:var(--surface);color:var(--ink);font-family:var(--f-num);font-size:18px;letter-spacing:normal}\n.field input:focus{outline:3px solid var(--accent);outline-offset:1px}\n.login-error{margin:0;padding:10px 12px;border-radius:10px;background:var(--ticket-soft);color:var(--danger);font-weight:700;font-size:13px}\n.login-btn{flex:none;margin-left:0;width:100%}\n\n/* toast */\n.toast{position:fixed;left:50%;top:calc(env(safe-area-inset-top,0px) + 12px);transform:translateX(-50%);z-index:30;display:flex;align-items:center;gap:12px;width:max-content;max-width:calc(100% - 32px);padding:12px 12px 12px 16px;border-radius:12px;background:var(--ink);color:var(--surface);box-shadow:var(--shadow);font-weight:500}\n.toast.error{background:var(--danger);color:var(--danger-ink)}\n.toast button{flex:0 0 auto;border:1px solid currentColor;background:transparent;color:inherit;border-radius:8px;padding:6px 10px;font-weight:700}\n\n@media (min-width:760px){\n  .register{grid-template-columns:minmax(0,1.2fr) minmax(320px,1fr);align-items:start}\n  .cart{position:sticky;top:calc(env(safe-area-inset-top,0px) + 12px)}\n  .tile{min-height:150px}\n  .tile-price{font-size:36px}\n  .kpis{grid-template-columns:repeat(2,minmax(0,1fr))}\n  .facts{grid-template-columns:repeat(3,minmax(0,1fr))}\n}\n@media (max-width:759px){\n  .tabs{order:3;width:100%;margin-left:0}\n  .tabs a{flex:1}\n  .checkout{position:fixed;left:0;right:0;bottom:0;z-index:20;border-radius:0;border-top:1px solid var(--line);padding:10px max(16px,env(safe-area-inset-right,0px)) calc(10px + env(safe-area-inset-bottom,0px)) max(16px,env(safe-area-inset-left,0px))}\n  body.view-register .app{padding-bottom:110px}\n  .total-amt{font-size:28px}\n}\n@media (max-width:520px){\n  .kpis{grid-template-columns:minmax(0,1fr)}\n}\n@media (max-width:420px){\n  .kpi-val{font-size:30px}\n  .tile-price{font-size:26px}\n}\n@media (prefers-reduced-motion: reduce){\n  *{transition:none!important;animation:none!important}\n  .tile:active{transform:none}\n}\n</style>\n\n<div class=\"app\">\n  <header class=\"top\">\n    <h1 class=\"brand\"><b>DOPE</b><span>レジ</span></h1>\n    <span class=\"status\" id=\"status\" data-s=\"connecting\">接続中…</span>\n    <button type=\"button\" class=\"link-btn\" id=\"logoutBtn\" hidden>ログアウト</button>\n    <nav class=\"tabs\" aria-label=\"画面切り替え\">\n      <a href=\"#register\" data-view=\"register\" aria-current=\"page\">レジ</a>\n      <a href=\"#summary\" data-view=\"summary\">集計</a>\n      <a href=\"#history\" data-view=\"history\">履歴</a>\n    </nav>\n  </header>\n\n  <main>\n    <section id=\"view-register\" class=\"register\" aria-label=\"レジ\">\n      <div class=\"board\">\n        <div class=\"row-head\">\n          <span class=\"row-title\">通常</span>\n          <span class=\"row-note\">1杯 ¥300 ・ バニラアイス +¥200</span>\n        </div>\n        <div class=\"tiles\">\n          <button type=\"button\" class=\"tile\" data-item=\"normal\" aria-label=\"通常 ドリンク 300円を追加\">\n            <span class=\"tile-name\">ドリンク</span>\n            <span class=\"tile-price\">¥300</span>\n            <span class=\"tile-count\" hidden></span>\n          </button>\n          <button type=\"button\" class=\"tile\" data-item=\"normalIce\" aria-label=\"通常 ドリンク バニラアイス付き 500円を追加\">\n            <span class=\"tile-name\">ドリンク</span>\n            <span class=\"chip\">＋バニラアイス</span>\n            <span class=\"tile-price\">¥500</span>\n            <span class=\"tile-count\" hidden></span>\n          </button>\n        </div>\n        <div class=\"row-head ticket\">\n          <span class=\"row-title\">ライブチケット購入者</span>\n          <span class=\"row-note\">ドリンク代 無料 ・ アイスは +¥200</span>\n        </div>\n        <div class=\"tiles\">\n          <button type=\"button\" class=\"tile ticket\" data-item=\"ticket\" aria-label=\"チケット購入者 ドリンク 無料を追加\">\n            <span class=\"tile-name\">ドリンク</span>\n            <span class=\"tile-price\">¥0<s>¥300</s></span>\n            <span class=\"tile-count\" hidden></span>\n          </button>\n          <button type=\"button\" class=\"tile ticket\" data-item=\"ticketIce\" aria-label=\"チケット購入者 ドリンク バニラアイス付き 200円を追加\">\n            <span class=\"tile-name\">ドリンク</span>\n            <span class=\"chip\">＋バニラアイス</span>\n            <span class=\"tile-price\">¥200<s>¥500</s></span>\n            <span class=\"tile-count\" hidden></span>\n          </button>\n        </div>\n        <p class=\"notice\" id=\"readonlyNotice\" hidden><strong>この端末は閲覧のみです。</strong>会計を記録するには、オーナーにこのページの「編集者」として招待してもらってください。</p>\n        <p class=\"notice\" id=\"localNotice\" hidden><strong>この端末だけに記録しています。</strong>2台の端末で売上を共有するには、claude.ai のリンクから開いてください。</p>\n      </div>\n\n      <aside class=\"cart\" aria-label=\"ご注文\">\n        <div class=\"receipt\">\n          <div class=\"receipt-head\">\n            <h2>ご注文</h2>\n            <button type=\"button\" class=\"link-btn\" id=\"clearBtn\" hidden>すべてクリア</button>\n          </div>\n          <ul class=\"lines\" id=\"cartLines\"></ul>\n          <p class=\"empty\" id=\"cartEmpty\">上のボタンをタップすると、ここに追加されます。チケット購入者のドリンクはピンクのボタンです。</p>\n          <p class=\"free-note\" id=\"freeNote\" hidden>チケット特典のみ。お支払いはありません。</p>\n          <div class=\"pay\" id=\"paySection\" hidden>\n            <hr class=\"perf\">\n            <div class=\"pay-label\">お預かり</div>\n            <div class=\"quick\" id=\"quick\">\n              <button type=\"button\" data-recv=\"exact\" aria-pressed=\"false\">ちょうど</button>\n              <button type=\"button\" data-recv=\"500\" aria-pressed=\"false\">¥500</button>\n              <button type=\"button\" data-recv=\"1000\" aria-pressed=\"false\">¥1,000</button>\n              <button type=\"button\" data-recv=\"5000\" aria-pressed=\"false\">¥5,000</button>\n              <button type=\"button\" data-recv=\"10000\" aria-pressed=\"false\">¥10,000</button>\n            </div>\n            <label class=\"recv\" for=\"recvInput\"><span>¥</span><input id=\"recvInput\" type=\"text\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"その他の金額を入力\"></label>\n            <div class=\"change idle\" id=\"changeRow\"><span id=\"changeLabel\">お釣り</span><strong id=\"changeAmt\">お預かりを選ぶと表示します</strong></div>\n          </div>\n        </div>\n        <div class=\"checkout\" id=\"checkoutBar\">\n          <div class=\"total\">\n            <span class=\"total-label\">合計</span>\n            <span class=\"total-amt\" id=\"totalAmt\">¥0</span>\n            <span class=\"total-cups\" id=\"totalCups\">まだ選ばれていません</span>\n          </div>\n          <button type=\"button\" class=\"checkout-btn\" id=\"checkoutBtn\" disabled>接続中…</button>\n        </div>\n      </aside>\n    </section>\n\n    <section id=\"view-summary\" class=\"stack\" aria-label=\"集計\" hidden>\n      <div class=\"chips\" id=\"dayChips\" role=\"group\" aria-label=\"集計する日\"></div>\n      <div class=\"kpis\">\n        <div class=\"kpi\">\n          <span class=\"kpi-label\">売上合計</span>\n          <span class=\"kpi-val\" id=\"kSales\">¥0</span>\n          <span class=\"kpi-sub\" id=\"kTx\">会計 0回</span>\n        </div>\n        <div class=\"kpi\">\n          <span class=\"kpi-label\">出たドリンク</span>\n          <span class=\"kpi-val\" id=\"kCups\">0杯</span>\n          <div class=\"split\" aria-hidden=\"true\"><i class=\"p\" id=\"splitP\" style=\"width:0%\"></i><i class=\"t\" id=\"splitT\" style=\"width:0%\"></i></div>\n          <div class=\"legend\"><span><i class=\"dot p\"></i>通常 <b id=\"kPaid\">0</b>杯</span><span><i class=\"dot t\"></i>チケット <b id=\"kTicket\">0</b>杯</span></div>\n        </div>\n      </div>\n      <div class=\"panel\">\n        <table>\n          <thead><tr><th>内訳</th><th>杯数</th><th>金額</th></tr></thead>\n          <tbody id=\"breakdown\"></tbody>\n        </table>\n      </div>\n      <div class=\"facts\">\n        <div class=\"fact\"><span>バニラアイス</span><b id=\"fIce\">0個</b></div>\n        <div class=\"fact\"><span>チケット特典で無料にした額</span><b id=\"fFree\">¥0</b></div>\n        <div class=\"fact\"><span>取り消した会計</span><b id=\"fVoid\">0件</b></div>\n      </div>\n      <div class=\"panel\" id=\"perDayPanel\" hidden>\n        <table>\n          <thead><tr><th>営業日</th><th>通常</th><th>チケット</th><th>アイス</th><th>売上</th></tr></thead>\n          <tbody id=\"perDay\"></tbody>\n        </table>\n      </div>\n      <div class=\"actions\">\n        <button type=\"button\" class=\"btn primary\" id=\"copyBtn\">集計をコピー</button>\n        <button type=\"button\" class=\"btn\" id=\"csvBtn\" hidden>CSVを保存</button>\n      </div>\n      <textarea class=\"copy-fallback\" id=\"copyFallback\" readonly hidden aria-label=\"集計テキスト\"></textarea>\n      <p class=\"fine\">営業日は朝6時で区切っています（深夜0〜6時の売上は前日分）。取り消した会計は集計に含みません。</p>\n    </section>\n\n    <section id=\"view-history\" aria-label=\"履歴\" hidden>\n      <div id=\"historyList\"></div>\n      <p class=\"empty\" id=\"historyEmpty\">まだ会計がありません。レジでドリンクを選んで「会計する」を押すと、ここに記録されます。</p>\n    </section>\n  </main>\n</div>\n\n<div class=\"login\" id=\"login\" hidden>\n  <form class=\"login-card\" id=\"loginForm\" novalidate>\n    <h2 class=\"brand\"><b>DOPE</b><span>レジ</span></h2>\n    <p class=\"login-lead\">スタッフ用のIDとパスワードでログインしてください。</p>\n    <label class=\"field\" for=\"loginId\">ID\n      <input id=\"loginId\" name=\"username\" autocomplete=\"username\" autocapitalize=\"off\" autocorrect=\"off\" spellcheck=\"false\">\n    </label>\n    <label class=\"field\" for=\"loginPw\">パスワード\n      <input id=\"loginPw\" name=\"password\" type=\"password\" autocomplete=\"current-password\">\n    </label>\n    <p class=\"login-error\" id=\"loginError\" role=\"alert\" hidden></p>\n    <button type=\"submit\" class=\"checkout-btn login-btn\" id=\"loginBtn\">ログイン</button>\n    <p class=\"fine\">一度ログインすると、この端末では30日間そのまま使えます。</p>\n  </form>\n</div>\n\n<div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\" hidden><span id=\"toastMsg\"></span><button type=\"button\" id=\"toastAction\" hidden></button></div>\n\n<script>\n(function () {\n  'use strict';\n\n  // ---- 料金 -------------------------------------------------------------\n  // ドリンク1杯の値段とバニラアイスの追加料金。値段を変えるときはここだけ直す。\n  var PRICE = { drink: 300, ice: 200 };\n  var KEYS = ['normal', 'normalIce', 'ticket', 'ticketIce'];\n  var DAY_CUTOFF_HOURS = 6; // 営業日の区切り（朝6時）\n  var SYNC_MS = 10000;      // サーバー版で他の端末の会計を取りに行く間隔\n  var LS_SALES = 'dope-register:sales:v1';\n  var LS_CART = 'dope-register:cart:v1';\n  var LS_TOKEN = 'dope-register:token:v1';\n  var LS_OUTBOX = 'dope-register:outbox:v1';\n  // Cloudflare Worker から配信されたときだけ設定される（例: \"/api\"）\n  var API_BASE = typeof window.DOPE_API === 'string' ? window.DOPE_API : null;\n\n  function priceFor(key, p) {\n    p = p || PRICE;\n    if (key === 'normal') return p.drink;\n    if (key === 'normalIce') return p.drink + p.ice;\n    if (key === 'ticket') return 0;            // チケット購入者はドリンク代無料\n    if (key === 'ticketIce') return p.ice;     // アイス代だけいただく\n    return 0;\n  }\n  var isTicket = function (k) { return k === 'ticket' || k === 'ticketIce'; };\n  var hasIce = function (k) { return k === 'normalIce' || k === 'ticketIce'; };\n\n  // ---- state --------------------------------------------------------------\n  var state = {\n    cart: { normal: 0, normalIce: 0, ticket: 0, ticketIce: 0 },\n    recv: null,                // null | {mode:'exact'} | {mode:'amount', value, src}\n    sales: [],                 // newest first\n    loaded: false,\n    mode: 'connecting',        // connecting | server | shared | local\n    syncError: false,\n    canWrite: true,\n    loggedIn: true,\n    view: 'register',\n    dayFilter: 'today',\n    busy: false\n  };\n  var salesCol = null;\n  var downloads = null;\n  var localOk = true;\n  var pendingVoid = null, pendingVoidTimer = null;\n  // server mode\n  var token = null, serverSales = [], serverVersion = null, outbox = [], syncing = false, syncAgain = false;\n\n  var $ = function (id) { return document.getElementById(id); };\n\n  // ---- helpers ------------------------------------------------------------\n  function yen(n) { return '¥' + Math.round(n || 0).toLocaleString('ja-JP'); }\n  function pad(n) { return String(n).padStart(2, '0'); }\n  function bizDay(ts) {\n    var d = new Date(ts - DAY_CUTOFF_HOURS * 3600 * 1000);\n    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());\n  }\n  function dayLabel(day) {\n    var p = day.split('-').map(Number);\n    var w = '日月火水木金土'[new Date(p[0], p[1] - 1, p[2]).getDay()];\n    return p[1] + '/' + p[2] + '(' + w + ')';\n  }\n  function timeLabel(ts) { var d = new Date(ts); return pad(d.getHours()) + ':' + pad(d.getMinutes()); }\n  function dateTimeLabel(ts) {\n    var d = new Date(ts);\n    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());\n  }\n  function esc(s) {\n    return String(s).replace(/[&<>\"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]; });\n  }\n  function sleep(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }\n  function rid() { return Math.random().toString(36).slice(2, 7); }\n  function makeId(ts) { return 's' + ts.toString(36) + '-' + rid(); }\n  function saleDay(s) { return s.day || bizDay(s.ts || 0); }\n  function itemsOf(s) { var it = s.items || {}; var o = {}; KEYS.forEach(function (k) { o[k] = Number(it[k]) || 0; }); return o; }\n  function lsGet(k) { try { return localStorage.getItem(k); } catch (e) { return null; } }\n  function lsSet(k, v) { try { localStorage.setItem(k, v); return true; } catch (e) { return false; } }\n  function lsDel(k) { try { localStorage.removeItem(k); } catch (e) { /* ignore */ } }\n\n  function cartTotals() {\n    var total = 0, cups = 0;\n    KEYS.forEach(function (k) { total += priceFor(k) * state.cart[k]; cups += state.cart[k]; });\n    return { total: total, cups: cups };\n  }\n  function receivedValue(total) {\n    if (!state.recv) return null;\n    if (state.recv.mode === 'exact') return total;\n    return state.recv.value;\n  }\n  function saveCartDraft() { lsSet(LS_CART, JSON.stringify(state.cart)); }\n  function sortSales() { state.sales.sort(function (a, b) { return (b.ts || 0) - (a.ts || 0); }); }\n\n  // ---- server mode (Cloudflare Worker) ------------------------------------------\n  // 会計はまず端末内の「送信待ち」に入れてから送るので、電波が切れても会計できる。\n  async function api(fn, body) {\n    var r = await fetch(API_BASE + '/' + fn, {\n      method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body)\n    });\n    if (r.status === 401) return { ok: false, error: 'auth' };\n    if (!r.ok && r.status !== 429) throw new Error('http ' + r.status);\n    return r.json();\n  }\n  function loadOutbox() {\n    try { var v = JSON.parse(lsGet(LS_OUTBOX) || '[]'); return Array.isArray(v) ? v : []; } catch (e) { return []; }\n  }\n  function saveOutbox() { lsSet(LS_OUTBOX, JSON.stringify(outbox)); }\n  function mergeServer() {\n    var map = {}, list = [];\n    serverSales.forEach(function (s) { var c = Object.assign({}, s); map[c.id] = c; list.push(c); });\n    outbox.forEach(function (op) {\n      if (op.type === 'add' && op.sale) {\n        if (!map[op.sale.id]) { var c = Object.assign({}, op.sale, { pending: true }); map[c.id] = c; list.push(c); }\n      } else if (op.type === 'void' && map[op.id]) {\n        map[op.id].voided = !!op.voided; map[op.id].pending = true;\n      }\n    });\n    state.sales = list; sortSales();\n  }\n  function queue(op) {\n    op.opId = 'o' + Date.now().toString(36) + rid();\n    outbox.push(op); saveOutbox();\n    mergeServer(); renderData(); renderStatus();\n    syncNow();\n  }\n  async function syncNow() {\n    if (state.mode !== 'server' || !token) return;\n    if (syncing) { syncAgain = true; return; }\n    syncing = true;\n    var ops = outbox.slice();\n    try {\n      var res = await api('sync', { token: token, ops: ops, version: serverVersion });\n      if (res && res.ok) {\n        var done = {};\n        (res.applied || []).forEach(function (id) { done[id] = true; });\n        outbox = outbox.filter(function (o) { return !done[o.opId]; });\n        saveOutbox();\n        if (res.sales) serverSales = res.sales;\n        serverVersion = res.version;\n        state.loaded = true; state.syncError = false;\n      } else if (res && res.error === 'auth') {\n        loggedOut('ログインの期限が切れました。もう一度ログインしてください。');\n      } else {\n        state.syncError = true;\n      }\n    } catch (e) { state.syncError = true; }\n    syncing = false;\n    mergeServer(); renderData(); renderStatus();\n    if (syncAgain) { syncAgain = false; syncNow(); }\n  }\n  function showLogin(msg) {\n    $('login').hidden = false;\n    $('loginError').hidden = !msg; $('loginError').textContent = msg || '';\n  }\n  function loggedOut(msg) {\n    token = null; lsDel(LS_TOKEN); state.loggedIn = false;\n    showLogin(msg); renderStatus(); renderCheckout();\n  }\n  async function submitLogin(e) {\n    e.preventDefault();\n    var id = $('loginId').value.trim(), pw = $('loginPw').value;\n    if (!id || !pw) { showLogin('IDとパスワードを入力してください。'); return; }\n    var btn = $('loginBtn');\n    btn.disabled = true; btn.textContent = '確認中…';\n    try {\n      var res = await api('login', { id: id, password: pw });\n      if (res && res.ok) {\n        token = res.token; lsSet(LS_TOKEN, token); state.loggedIn = true;\n        $('loginPw').value = ''; $('login').hidden = true;\n        renderAll(); syncNow();\n      } else if (res && res.error === 'locked') {\n        showLogin('ログインの失敗が続いたので、10分ほど待ってからもう一度試してください。');\n      } else if (res && res.error === 'not_configured') {\n        showLogin('サーバーにIDとパスワードがまだ設定されていません（LOGIN_ID / LOGIN_PASSWORD）。');\n      } else {\n        showLogin('IDかパスワードが違います。');\n      }\n    } catch (err) {\n      showLogin('サーバーにつながりません。電波を確認して、もう一度試してください。');\n    }\n    btn.disabled = false; btn.textContent = 'ログイン';\n  }\n\n  // ---- storage (claude.ai / この端末のみ) ---------------------------------------\n  function loadLocalSales() {\n    try { var raw = localStorage.getItem(LS_SALES); return raw ? JSON.parse(raw) : []; }\n    catch (e) { return null; }\n  }\n  function persistLocal() { localOk = lsSet(LS_SALES, JSON.stringify(state.sales)); }\n\n  async function withRetry(fn) {\n    try { return await fn(); }\n    catch (e) {\n      var code = e && e.code;\n      var known = ['invalid_argument', 'quota_exceeded', 'revoked', 'not_granted', 'capability_disabled', 'capability_removed', 'transform_error', 'resource_exhausted'];\n      if (known.indexOf(code) !== -1) throw e;\n      await sleep(400 + Math.random() * 800);\n      return await fn();\n    }\n  }\n\n  async function writeSale(sale) {\n    if (state.mode === 'server') { queue({ type: 'add', sale: sale }); return; }\n    if (state.mode === 'shared') {\n      var body = Object.assign({}, sale); delete body.id;\n      await withRetry(function () { return salesCol.doc(sale.id).set(body); });\n      return;\n    }\n    state.sales.unshift(sale); sortSales(); persistLocal();\n    if (!localOk) throw { code: 'local_failed' };\n  }\n  async function updateSale(id, patch) {\n    if (state.mode === 'server') { queue({ type: 'void', id: id, voided: !!patch.voided, at: Date.now() }); return; }\n    if (state.mode === 'shared') {\n      await withRetry(function () { return salesCol.doc(id).update(patch); });\n      return;\n    }\n    var s = state.sales.find(function (x) { return x.id === id; });\n    if (s) { Object.assign(s, patch); persistLocal(); }\n  }\n\n  function handleWriteError(e) {\n    var code = e && e.code;\n    if (code === 'invalid_argument' || code === 'not_granted') {\n      state.canWrite = false; renderStatus(); renderCheckout();\n      toast('この端末には記録する権限がありません。オーナーに「編集者」として招待してもらってください。', { error: true, ms: 8000 });\n    } else if (code === 'quota_exceeded') {\n      toast('保存できる件数の上限に達しました。古い記録の整理が必要です。', { error: true, ms: 8000 });\n    } else if (code === 'local_failed') {\n      toast('この端末に保存できませんでした。プライベートブラウズを解除してください。', { error: true, ms: 8000 });\n    } else {\n      toast('保存できませんでした。通信を確認して、もう一度「会計する」を押してください。', { error: true, ms: 8000 });\n    }\n  }\n\n  // ---- connection -------------------------------------------------------------\n  var resubscribed = false;\n  function subscribe() {\n    salesCol.onSnapshot(function (snap) {\n      state.sales = snap.docs.map(function (d) { return Object.assign({ id: d.id }, d.data()); });\n      sortSales();\n      state.loaded = true;\n      state.syncError = false;\n      renderData(); renderStatus();\n    }, function (err) {\n      if (err && err.code === 'unavailable' && !resubscribed) {\n        resubscribed = true; setTimeout(subscribe, 2000); return;\n      }\n      state.syncError = true; renderStatus();\n    });\n  }\n\n  async function connect() {\n    if (API_BASE !== null) {\n      state.mode = 'server';\n      token = lsGet(LS_TOKEN);\n      outbox = loadOutbox();\n      state.loggedIn = !!token;\n      mergeServer();\n      if (!token) showLogin();\n      renderAll();\n      syncNow();\n      setInterval(function () { if (!document.hidden) syncNow(); }, SYNC_MS);\n      document.addEventListener('visibilitychange', function () { if (!document.hidden) syncNow(); });\n      window.addEventListener('online', syncNow);\n      return;\n    }\n    var claudeApi = window.claude && typeof window.claude.use === 'function' ? window.claude : null;\n    var db = null;\n    if (claudeApi) { try { db = await claudeApi.use('db'); } catch (e) { db = null; } }\n    if (db) {\n      state.mode = 'shared';\n      salesCol = db.collection('sales');\n      subscribe();\n      try {\n        var user = await claudeApi.use('user');\n        if (user) { var w = await user.can('data.write'); if (w === false) state.canWrite = false; }\n      } catch (e) { /* keep inputs; a refused write decides */ }\n    } else {\n      state.mode = 'local';\n      var list = loadLocalSales();\n      localOk = list !== null;\n      state.sales = Array.isArray(list) ? list : [];\n      sortSales();\n      state.loaded = true;\n    }\n    if (claudeApi) {\n      try { downloads = await claudeApi.use('downloads'); } catch (e) { downloads = null; }\n    }\n    renderAll();\n  }\n\n  // ---- actions ----------------------------------------------------------------\n  function addItem(k, delta) {\n    state.cart[k] = Math.max(0, Math.min(99, state.cart[k] + delta));\n    saveCartDraft();\n    renderCart();\n  }\n  function clearCart() {\n    KEYS.forEach(function (k) { state.cart[k] = 0; });\n    state.recv = null;\n    $('recvInput').value = '';\n    saveCartDraft();\n    renderCart();\n  }\n  function canCheckout() {\n    return state.mode !== 'connecting' && state.canWrite && state.loggedIn && !state.busy;\n  }\n\n  async function checkout() {\n    var t = cartTotals();\n    if (!t.cups || !canCheckout()) return;\n    var recv = t.total > 0 ? receivedValue(t.total) : null;\n    if (recv !== null && recv < t.total) return;\n    var ts = Date.now();\n    var items = Object.assign({}, state.cart);\n    var sale = {\n      id: makeId(ts),\n      ts: ts,\n      day: bizDay(ts),\n      items: items,\n      cups: t.cups,\n      ice: items.normalIce + items.ticketIce,\n      total: t.total,\n      received: recv,\n      change: recv === null ? null : recv - t.total,\n      prices: { drink: PRICE.drink, ice: PRICE.ice },\n      voided: false\n    };\n    var prevCart = Object.assign({}, state.cart), prevRecv = state.recv, prevInput = $('recvInput').value;\n    clearCart();\n    state.busy = true; renderCheckout();\n    try {\n      await writeSale(sale);\n      if (state.mode === 'local') renderData();\n      var msg = '会計しました ' + yen(sale.total) + (sale.change ? '・お釣り ' + yen(sale.change) : '');\n      toast(msg, { action: '取り消す', onAction: function () { setVoided(sale.id, true); }, ms: 7000 });\n    } catch (e) {\n      state.cart = prevCart; state.recv = prevRecv; $('recvInput').value = prevInput;\n      saveCartDraft(); renderCart();\n      handleWriteError(e);\n    } finally {\n      state.busy = false; renderCheckout();\n    }\n  }\n\n  async function setVoided(id, voided) {\n    try {\n      await updateSale(id, { voided: voided, voidedAt: voided ? Date.now() : null });\n      if (state.mode === 'local') renderData();\n      toast(voided ? '会計を取り消しました' : '会計を元に戻しました');\n    } catch (e) { handleWriteError(e); }\n  }\n\n  // ---- tally ------------------------------------------------------------------\n  function tally(list) {\n    var t = { normal: 0, normalIce: 0, ticket: 0, ticketIce: 0, amt: { normal: 0, normalIce: 0, ticket: 0, ticketIce: 0 }, sales: 0, tx: 0, freed: 0, voided: 0 };\n    list.forEach(function (s) {\n      if (s.voided) { t.voided++; return; }\n      var it = itemsOf(s), p = s.prices || PRICE;\n      KEYS.forEach(function (k) { t[k] += it[k]; t.amt[k] += priceFor(k, p) * it[k]; });\n      t.freed += (it.ticket + it.ticketIce) * (p.drink || 0);\n      t.sales += Number(s.total) || 0;\n      t.tx++;\n    });\n    t.paidCups = t.normal + t.normalIce;\n    t.ticketCups = t.ticket + t.ticketIce;\n    t.cups = t.paidCups + t.ticketCups;\n    t.ice = t.normalIce + t.ticketIce;\n    return t;\n  }\n  function filteredSales() {\n    if (state.dayFilter === 'all') return state.sales;\n    var day = state.dayFilter === 'today' ? bizDay(Date.now()) : state.dayFilter;\n    return state.sales.filter(function (s) { return saleDay(s) === day; });\n  }\n  function filterLabel() {\n    if (state.dayFilter === 'all') return '全期間';\n    var day = state.dayFilter === 'today' ? bizDay(Date.now()) : state.dayFilter;\n    return dayLabel(day);\n  }\n\n  // ---- render -----------------------------------------------------------------\n  function renderStatus() {\n    var el = $('status'), s, text;\n    if (state.mode === 'server') {\n      var n = outbox.length;\n      if (!state.loggedIn) { s = 'connecting'; text = 'ログインしてください'; }\n      else if (state.syncError) { s = 'local'; text = n ? 'オフライン・未送信 ' + n + '件' : 'オフライン'; }\n      else if (n) { s = 'local'; text = '送信中・' + n + '件'; }\n      else if (!state.loaded) { s = 'connecting'; text = '接続中…'; }\n      else { s = 'shared'; text = '全端末で共有中'; }\n    }\n    else if (state.mode === 'connecting') { s = 'connecting'; text = '接続中…'; }\n    else if (!state.canWrite) { s = 'readonly'; text = '閲覧のみ'; }\n    else if (state.syncError) { s = 'error'; text = '同期が止まっています・再読み込みしてください'; }\n    else if (state.mode === 'shared') { s = 'shared'; text = '全端末で共有中'; }\n    else { s = 'local'; text = localOk ? 'この端末のみに保存' : '保存できません'; }\n    el.dataset.s = s; el.textContent = text;\n    $('readonlyNotice').hidden = state.canWrite || state.mode === 'connecting';\n    $('localNotice').hidden = state.mode !== 'local';\n    $('logoutBtn').hidden = !(state.mode === 'server' && state.loggedIn);\n  }\n\n  function renderTiles() {\n    document.querySelectorAll('.tile').forEach(function (b) {\n      var n = state.cart[b.dataset.item];\n      var badge = b.querySelector('.tile-count');\n      badge.hidden = !n; badge.textContent = n;\n      b.classList.toggle('has-count', n > 0);\n    });\n  }\n\n  function lineName(k) {\n    return '<span class=\"tag' + (isTicket(k) ? ' ticket' : '') + '\">' + (isTicket(k) ? 'チケット' : '通常') + '</span>ドリンク' +\n      (hasIce(k) ? '<span class=\"chip\">＋バニラアイス</span>' : '');\n  }\n\n  function renderCart() {\n    renderTiles();\n    var keys = KEYS.filter(function (k) { return state.cart[k] > 0; });\n    $('cartLines').innerHTML = keys.map(function (k) {\n      var n = state.cart[k];\n      return '<li class=\"line\"><div class=\"line-name\">' + lineName(k) + '</div>' +\n        '<div class=\"qty\"><button type=\"button\" data-dec=\"' + k + '\" aria-label=\"1つ減らす\">−</button><span>' + n + '</span>' +\n        '<button type=\"button\" data-inc=\"' + k + '\" aria-label=\"1つ増やす\">＋</button></div>' +\n        '<div class=\"line-amt\">' + yen(priceFor(k) * n) + '</div></li>';\n    }).join('');\n    var t = cartTotals();\n    $('cartEmpty').hidden = keys.length > 0;\n    $('clearBtn').hidden = keys.length === 0;\n    $('freeNote').hidden = !(keys.length > 0 && t.total === 0);\n    $('paySection').hidden = !(t.total > 0);\n\n    document.querySelectorAll('#quick button').forEach(function (b) {\n      var v = b.dataset.recv;\n      var on = !!state.recv && ((v === 'exact' && state.recv.mode === 'exact') ||\n        (state.recv.mode === 'amount' && state.recv.src === 'quick' && String(state.recv.value) === v));\n      b.setAttribute('aria-pressed', on ? 'true' : 'false');\n    });\n\n    var recv = receivedValue(t.total);\n    var row = $('changeRow');\n    row.classList.remove('idle', 'short');\n    if (recv === null) {\n      row.classList.add('idle'); $('changeLabel').textContent = 'お釣り'; $('changeAmt').textContent = 'お預かりを選ぶと表示します';\n    } else if (recv < t.total) {\n      row.classList.add('short'); $('changeLabel').textContent = '足りません'; $('changeAmt').textContent = 'あと ' + yen(t.total - recv);\n    } else {\n      $('changeLabel').textContent = 'お釣り'; $('changeAmt').textContent = yen(recv - t.total);\n    }\n    renderCheckout();\n  }\n\n  function renderCheckout() {\n    var t = cartTotals();\n    $('totalAmt').textContent = yen(t.total);\n    $('totalCups').textContent = t.cups ? t.cups + '杯' : 'まだ選ばれていません';\n    var recv = t.total > 0 ? receivedValue(t.total) : null;\n    var short = recv !== null && recv < t.total;\n    var btn = $('checkoutBtn'), label = '会計する', disabled = !t.cups || short || state.busy;\n    if (state.mode === 'connecting') { label = '接続中…'; disabled = true; }\n    else if (!state.loggedIn) { label = 'ログインしてください'; disabled = true; }\n    else if (!state.canWrite) { label = '閲覧のみ'; disabled = true; }\n    else if (state.busy) { label = '記録中…'; }\n    btn.textContent = label; btn.disabled = disabled;\n  }\n\n  function renderSummary() {\n    var today = bizDay(Date.now());\n    var days = [];\n    state.sales.forEach(function (s) { var d = saleDay(s); if (d !== today && days.indexOf(d) === -1) days.push(d); });\n    days.sort().reverse();\n    var chips = [{ v: 'today', l: '今日 ' + dayLabel(today) }].concat(days.map(function (d) { return { v: d, l: dayLabel(d) }; }));\n    chips.push({ v: 'all', l: '全期間' });\n    $('dayChips').innerHTML = chips.map(function (c) {\n      return '<button type=\"button\" data-day=\"' + esc(c.v) + '\" aria-pressed=\"' + (state.dayFilter === c.v ? 'true' : 'false') + '\">' + esc(c.l) + '</button>';\n    }).join('');\n\n    var t = tally(filteredSales());\n    $('kSales').textContent = yen(t.sales);\n    $('kTx').textContent = '会計 ' + t.tx + '回';\n    $('kCups').textContent = t.cups + '杯';\n    $('kPaid').textContent = t.paidCups;\n    $('kTicket').textContent = t.ticketCups;\n    $('splitP').style.width = (t.cups ? t.paidCups / t.cups * 100 : 0) + '%';\n    $('splitT').style.width = (t.cups ? t.ticketCups / t.cups * 100 : 0) + '%';\n\n    var rows = [\n      ['group paid', '通常（有料）', t.paidCups, t.amt.normal + t.amt.normalIce],\n      ['sub', 'ドリンクのみ', t.normal, t.amt.normal],\n      ['sub', '＋バニラアイス', t.normalIce, t.amt.normalIce],\n      ['group ticket', 'チケット購入者', t.ticketCups, t.amt.ticket + t.amt.ticketIce],\n      ['sub', 'ドリンクのみ（無料）', t.ticket, t.amt.ticket],\n      ['sub', '＋バニラアイス（アイス代）', t.ticketIce, t.amt.ticketIce],\n      ['grand', '合計', t.cups, t.sales]\n    ];\n    $('breakdown').innerHTML = rows.map(function (r) {\n      return '<tr class=\"' + r[0] + '\"><td>' + r[1] + '</td><td class=\"num\">' + r[2] + '杯</td><td class=\"num\">' + yen(r[3]) + '</td></tr>';\n    }).join('');\n    $('fIce').textContent = t.ice + '個';\n    $('fFree').textContent = yen(t.freed);\n    $('fVoid').textContent = t.voided + '件';\n\n    var showPerDay = state.dayFilter === 'all' && state.sales.length > 0;\n    $('perDayPanel').hidden = !showPerDay;\n    if (showPerDay) {\n      var all = [];\n      state.sales.forEach(function (s) { var d = saleDay(s); if (all.indexOf(d) === -1) all.push(d); });\n      all.sort().reverse();\n      $('perDay').innerHTML = all.map(function (d) {\n        var x = tally(state.sales.filter(function (s) { return saleDay(s) === d; }));\n        return '<tr><td>' + esc(dayLabel(d)) + '</td><td class=\"num\">' + x.paidCups + '杯</td><td class=\"num\">' + x.ticketCups + '杯</td><td class=\"num\">' + x.ice + '個</td><td class=\"num\">' + yen(x.sales) + '</td></tr>';\n      }).join('');\n    }\n    // CSV: claude.ai では downloads 機能、サーバー版ではブラウザのダウンロード\n    $('csvBtn').hidden = !(downloads || state.mode === 'server' || state.mode === 'local');\n  }\n\n  function saleChips(s) {\n    var it = itemsOf(s);\n    return KEYS.filter(function (k) { return it[k] > 0; }).map(function (k) {\n      return '<span class=\"tag' + (isTicket(k) ? ' ticket' : '') + '\">' + (isTicket(k) ? 'チケット' : '通常') + (hasIce(k) ? '＋アイス' : '') + ' ×' + it[k] + '</span>';\n    }).join('');\n  }\n\n  function renderHistory() {\n    var list = state.sales;\n    $('historyEmpty').hidden = list.length > 0;\n    if (!list.length) { $('historyList').innerHTML = ''; return; }\n    var shown = list.slice(0, 300);\n    var html = '', current = null;\n    shown.forEach(function (s) {\n      var d = saleDay(s);\n      if (d !== current) {\n        if (current !== null) html += '</ul>';\n        var t = tally(list.filter(function (x) { return saleDay(x) === d; }));\n        html += '<div class=\"day-head\"><span>' + esc(dayLabel(d)) + '</span><span>' + t.cups + '杯・<b>' + yen(t.sales) + '</b></span></div><ul class=\"sales\">';\n        current = d;\n      }\n      var armed = pendingVoid === s.id;\n      var btn = s.voided\n        ? '<button type=\"button\" class=\"void-btn\" data-restore=\"' + esc(s.id) + '\">戻す</button>'\n        : '<button type=\"button\" class=\"void-btn' + (armed ? ' armed' : '') + '\" data-void=\"' + esc(s.id) + '\">' + (armed ? '本当に取消' : '取消') + '</button>';\n      var pay = (s.received !== null && s.received !== undefined) ? '<small>預 ' + yen(s.received) + '・釣 ' + yen(s.change) + '</small>' : '';\n      html += '<li class=\"sale' + (s.voided ? ' voided' : '') + '\">' +\n        '<span class=\"sale-time\">' + timeLabel(s.ts) + '</span>' +\n        '<div class=\"sale-items\">' + saleChips(s) + (s.voided ? '<span class=\"voided-mark\">取消済み</span>' : '') +\n        (s.pending ? '<span class=\"pending-mark\">未送信</span>' : '') + '</div>' +\n        '<div class=\"sale-amt\">' + yen(s.total) + pay + '</div>' + btn + '</li>';\n    });\n    html += '</ul>';\n    if (list.length > shown.length) html += '<p class=\"fine\">最新の300件を表示しています。集計にはすべての会計が入っています。</p>';\n    $('historyList').innerHTML = html;\n  }\n\n  function renderData() { renderSummary(); renderHistory(); }\n\n  function renderView() {\n    ['register', 'summary', 'history'].forEach(function (v) { $('view-' + v).hidden = state.view !== v; });\n    document.querySelectorAll('.tabs a').forEach(function (a) {\n      if (a.dataset.view === state.view) a.setAttribute('aria-current', 'page'); else a.removeAttribute('aria-current');\n    });\n    document.body.classList.toggle('view-register', state.view === 'register');\n  }\n\n  function renderAll() { renderStatus(); renderView(); renderCart(); renderData(); }\n\n  // ---- toast ------------------------------------------------------------------\n  var toastTimer = null;\n  function toast(msg, opts) {\n    opts = opts || {};\n    var el = $('toast'), btn = $('toastAction');\n    $('toastMsg').textContent = msg;\n    el.classList.toggle('error', !!opts.error);\n    if (opts.action) {\n      btn.hidden = false; btn.textContent = opts.action;\n      btn.onclick = function () { el.hidden = true; opts.onAction(); };\n    } else { btn.hidden = true; btn.onclick = null; }\n    el.hidden = false;\n    clearTimeout(toastTimer);\n    toastTimer = setTimeout(function () { el.hidden = true; }, opts.ms || 3500);\n  }\n\n  // ---- summary text / csv -------------------------------------------------------\n  function summaryText() {\n    var t = tally(filteredSales());\n    return [\n      'DOPE レジ集計 ' + filterLabel(),\n      '売上合計 ' + yen(t.sales) + '（会計 ' + t.tx + '回）',\n      '出たドリンク ' + t.cups + '杯',\n      '・通常 ' + t.paidCups + '杯（うちアイス付き ' + t.normalIce + '）' + yen(t.amt.normal + t.amt.normalIce),\n      '・チケット購入者 ' + t.ticketCups + '杯（うちアイス付き ' + t.ticketIce + '）' + yen(t.amt.ticket + t.amt.ticketIce),\n      'バニラアイス ' + t.ice + '個',\n      'チケット特典で無料にした額 ' + yen(t.freed)\n    ].join('\\n');\n  }\n  function csvCell(v) { var s = v === null || v === undefined ? '' : String(v); return /[\",\\n]/.test(s) ? '\"' + s.replace(/\"/g, '\"\"') + '\"' : s; }\n  function buildCsv(list) {\n    var head = ['日時', '営業日', '通常ドリンク', '通常＋アイス', 'チケットドリンク', 'チケット＋アイス', '杯数', 'アイス数', '金額', 'お預かり', 'お釣り', '取消'];\n    var rows = list.slice().sort(function (a, b) { return a.ts - b.ts; }).map(function (s) {\n      var it = itemsOf(s);\n      return [dateTimeLabel(s.ts), saleDay(s), it.normal, it.normalIce, it.ticket, it.ticketIce,\n        it.normal + it.normalIce + it.ticket + it.ticketIce, it.normalIce + it.ticketIce, s.total,\n        s.received === null || s.received === undefined ? '' : s.received,\n        s.change === null || s.change === undefined ? '' : s.change, s.voided ? '取消' : ''];\n    });\n    return '﻿' + [head].concat(rows).map(function (r) { return r.map(csvCell).join(','); }).join('\\r\\n');\n  }\n\n  // ---- routing ------------------------------------------------------------------\n  function route() {\n    var h = (location.hash || '').replace('#', '');\n    state.view = ['register', 'summary', 'history'].indexOf(h) !== -1 ? h : 'register';\n    renderView();\n  }\n\n  // ---- events -------------------------------------------------------------------\n  function bind() {\n    document.querySelectorAll('.tile').forEach(function (b) {\n      b.addEventListener('click', function () { addItem(b.dataset.item, 1); });\n    });\n    $('cartLines').addEventListener('click', function (e) {\n      var b = e.target.closest('button'); if (!b) return;\n      if (b.dataset.inc) addItem(b.dataset.inc, 1);\n      if (b.dataset.dec) addItem(b.dataset.dec, -1);\n    });\n    $('clearBtn').addEventListener('click', clearCart);\n    $('quick').addEventListener('click', function (e) {\n      var b = e.target.closest('button'); if (!b) return;\n      var v = b.dataset.recv;\n      state.recv = v === 'exact' ? { mode: 'exact' } : { mode: 'amount', value: Number(v), src: 'quick' };\n      $('recvInput').value = '';\n      renderCart();\n    });\n    $('recvInput').addEventListener('input', function (e) {\n      var digits = e.target.value.replace(/[^0-9０-９]/g, '').replace(/[０-９]/g, function (c) { return String.fromCharCode(c.charCodeAt(0) - 0xFEE0); });\n      if (e.target.value !== digits) e.target.value = digits;\n      state.recv = digits ? { mode: 'amount', value: Number(digits), src: 'input' } : null;\n      renderCart();\n    });\n    $('checkoutBtn').addEventListener('click', checkout);\n    $('loginForm').addEventListener('submit', submitLogin);\n    $('logoutBtn').addEventListener('click', function () { loggedOut(''); });\n\n    $('dayChips').addEventListener('click', function (e) {\n      var b = e.target.closest('button'); if (!b) return;\n      state.dayFilter = b.dataset.day; $('copyFallback').hidden = true; renderSummary();\n    });\n    $('copyBtn').addEventListener('click', function () {\n      var text = summaryText();\n      var fallback = function () {\n        var ta = $('copyFallback'); ta.value = text; ta.hidden = false; ta.focus(); ta.select();\n        toast('コピーできなかったので、下のテキストを長押ししてコピーしてください。');\n      };\n      try {\n        if (navigator.clipboard && navigator.clipboard.writeText) {\n          navigator.clipboard.writeText(text).then(function () { toast('集計をコピーしました'); }, fallback);\n        } else fallback();\n      } catch (e) { fallback(); }\n    });\n    $('csvBtn').addEventListener('click', async function () {\n      var label = state.dayFilter === 'all' ? 'all' : (state.dayFilter === 'today' ? bizDay(Date.now()) : state.dayFilter);\n      var filename = 'dope-register-' + label + '.csv';\n      var data = buildCsv(filteredSales());\n      if (downloads) {\n        try { await downloads.save({ filename: filename, data: data }); }\n        catch (e) { if (!e || e.code !== 'declined') toast('CSVを保存できませんでした。', { error: true }); }\n        return;\n      }\n      var url = URL.createObjectURL(new Blob([data], { type: 'text/csv' }));\n      var a = document.createElement('a'); a.href = url; a.download = filename;\n      document.body.appendChild(a); a.click(); a.remove();\n      setTimeout(function () { URL.revokeObjectURL(url); }, 5000);\n    });\n\n    $('historyList').addEventListener('click', function (e) {\n      var b = e.target.closest('button'); if (!b) return;\n      if (b.dataset.restore) { setVoided(b.dataset.restore, false); return; }\n      var id = b.dataset.void; if (!id) return;\n      if (!state.canWrite || !state.loggedIn) { toast('この端末では取り消せません。', { error: true }); return; }\n      if (pendingVoid === id) {\n        pendingVoid = null; clearTimeout(pendingVoidTimer); setVoided(id, true);\n      } else {\n        pendingVoid = id; renderHistory();\n        clearTimeout(pendingVoidTimer);\n        pendingVoidTimer = setTimeout(function () { pendingVoid = null; renderHistory(); }, 4000);\n      }\n    });\n\n    window.addEventListener('hashchange', route);\n  }\n\n  // ---- boot ---------------------------------------------------------------------\n  function start(saved) {\n    saved = saved || {};\n    var cart = saved.cart;\n    if (!cart) { try { cart = JSON.parse(lsGet(LS_CART) || 'null'); } catch (e) { cart = null; } }\n    if (cart) KEYS.forEach(function (k) { state.cart[k] = Math.max(0, Number(cart[k]) || 0); });\n    if (saved.dayFilter) state.dayFilter = saved.dayFilter;\n    bind();\n    route();\n    renderAll();\n    connect();\n  }\n\n  var hot = window.claude && window.claude.hot;\n  if (hot && typeof hot.snapshot === 'function') {\n    try { hot.snapshot(function () { return { cart: state.cart, dayFilter: state.dayFilter }; }); } catch (e) { /* ignore */ }\n  }\n  if (hot && typeof hot.ready === 'function') hot.ready(start);\n  else start((hot && hot.data) || {});\n})();\n</script>\n</body></html>";

/**
 * DOPE レジ — Cloudflare Worker
 *
 * ・GET  /           レジ画面（register.html）を返す
 * ・POST /api/login  ID / パスワードを確認してトークンを返す
 * ・POST /api/sync   端末の未送信の操作（会計・取消）を保存し、売上一覧を返す
 *
 * 必要な設定（Cloudflare のダッシュボード → Worker → 設定）
 * ・D1 データベースのバインディング: 変数名 DB
 * ・シークレット: LOGIN_ID, LOGIN_PASSWORD（任意で TOKEN_SECRET）
 */

const TOKEN_DAYS = 30;
const MAX_LOGIN_FAILS = 30;      // 10 分間にこれ以上失敗したら一時停止
const DAY_CUTOFF_HOURS = 6;
const JST_OFFSET_MS = 9 * 3600 * 1000;

const SCHEMA = [
  `CREATE TABLE IF NOT EXISTS sales (
    id TEXT PRIMARY KEY, ts INTEGER NOT NULL, day TEXT NOT NULL,
    normal INTEGER NOT NULL DEFAULT 0, normal_ice INTEGER NOT NULL DEFAULT 0,
    ticket INTEGER NOT NULL DEFAULT 0, ticket_ice INTEGER NOT NULL DEFAULT 0,
    cups INTEGER NOT NULL, ice INTEGER NOT NULL, total INTEGER NOT NULL,
    received INTEGER, change INTEGER, drink_price INTEGER NOT NULL, ice_price INTEGER NOT NULL,
    voided INTEGER NOT NULL DEFAULT 0, voided_at INTEGER)`,
  `CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v TEXT)`
];

let schemaReady = false;
async function ensureSchema(db) {
  if (schemaReady) return;
  await db.batch(SCHEMA.map((q) => db.prepare(q)));
  schemaReady = true;
}

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' }
  });
}

// ---- token ----------------------------------------------------------------------
const enc = new TextEncoder();
function b64url(buf) {
  let s = '';
  new Uint8Array(buf).forEach((b) => { s += String.fromCharCode(b); });
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
function getLogin(env) {
  return { id: String(env.LOGIN_ID || '').trim(), password: String(env.LOGIN_PASSWORD || '') };
}
// パスワードを変えると、それまでのトークンは使えなくなる
async function sign(payload, env, cfg) {
  const keyData = enc.encode((env.TOKEN_SECRET || 'dope-register') + ':' + cfg.id + ':' + cfg.password);
  const key = await crypto.subtle.importKey('raw', keyData, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return b64url(await crypto.subtle.sign('HMAC', key, enc.encode(payload)));
}
async function makeToken(env, cfg) {
  const payload = 'v1.' + (Date.now() + TOKEN_DAYS * 86400000);
  return payload + '.' + (await sign(payload, env, cfg));
}
async function verifyToken(token, env, cfg) {
  if (!cfg.id || !cfg.password || typeof token !== 'string') return false;
  const i = token.lastIndexOf('.');
  if (i < 0) return false;
  const payload = token.slice(0, i);
  if ((await sign(payload, env, cfg)) !== token.slice(i + 1)) return false;
  return Number(payload.split('.')[1]) > Date.now();
}

// ---- helpers --------------------------------------------------------------------
function bizDay(ts) {
  const d = new Date(ts + JST_OFFSET_MS - DAY_CUTOFF_HOURS * 3600000);
  return d.toISOString().slice(0, 10);
}
function num(v, fallback) {
  const n = Number(v);
  return v === null || v === undefined || v === '' || !Number.isFinite(n) ? fallback : n;
}
async function getMeta(db, k) {
  const row = await db.prepare('SELECT v FROM meta WHERE k = ?').bind(k).first();
  return row ? row.v : null;
}
function setMetaStmt(db, k, v) {
  return db.prepare('INSERT INTO meta (k, v) VALUES (?, ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v').bind(k, String(v));
}

/** 端末から届いた会計を検証し、金額はサーバー側で計算し直す */
function cleanSale(s) {
  if (!s || typeof s !== 'object') return null;
  const id = String(s.id || '');
  if (!/^[A-Za-z0-9_-]{4,64}$/.test(id)) return null;
  const ts = Number(s.ts);
  if (!Number.isFinite(ts) || ts <= 0) return null;
  const it = s.items || {};
  const n = (k) => Math.max(0, Math.min(999, Math.floor(Number(it[k]) || 0)));
  const items = { normal: n('normal'), normalIce: n('normalIce'), ticket: n('ticket'), ticketIce: n('ticketIce') };
  const cups = items.normal + items.normalIce + items.ticket + items.ticketIce;
  if (!cups) return null;
  const p = s.prices || {};
  const drink = Math.max(0, Math.floor(num(p.drink, 300)));
  const ice = Math.max(0, Math.floor(num(p.ice, 200)));
  const total = items.normal * drink + items.normalIce * (drink + ice) + items.ticketIce * ice;
  const received = s.received === null || s.received === undefined || s.received === ''
    ? null : Math.max(0, Math.floor(Number(s.received) || 0));
  const day = /^\d{4}-\d{2}-\d{2}$/.test(String(s.day || '')) ? String(s.day) : bizDay(ts);
  return { id, ts, day, items, cups, ice: items.normalIce + items.ticketIce, total, received,
    change: received === null ? null : received - total, drink, icePrice: ice };
}

function rowToSale(r) {
  return {
    id: r.id, ts: r.ts, day: r.day,
    items: { normal: r.normal, normalIce: r.normal_ice, ticket: r.ticket, ticketIce: r.ticket_ice },
    cups: r.cups, ice: r.ice, total: r.total, received: r.received, change: r.change,
    prices: { drink: r.drink_price, ice: r.ice_price }, voided: !!r.voided
  };
}

// ---- API ------------------------------------------------------------------------
async function apiLogin(body, env) {
  const cfg = getLogin(env);
  if (!cfg.id || !cfg.password) return json({ ok: false, error: 'not_configured' });
  const db = env.DB;
  let fails = { n: 0, since: Date.now() };
  try { fails = JSON.parse((await getMeta(db, 'login_fails')) || 'null') || fails; } catch (e) { /* reset */ }
  if (Date.now() - fails.since > 600000) fails = { n: 0, since: Date.now() };
  if (fails.n >= MAX_LOGIN_FAILS) return json({ ok: false, error: 'locked' }, 429);
  if (String(body.id || '').trim() === cfg.id && String(body.password || '') === cfg.password) {
    return json({ ok: true, token: await makeToken(env, cfg) });
  }
  fails.n += 1;
  await setMetaStmt(db, 'login_fails', JSON.stringify(fails)).run();
  return json({ ok: false, error: 'invalid' });
}

async function apiSync(body, env) {
  const cfg = getLogin(env);
  if (!(await verifyToken(body.token, env, cfg))) return json({ ok: false, error: 'auth' }, 401);
  const db = env.DB;
  const ops = Array.isArray(body.ops) ? body.ops.slice(0, 300) : [];
  const applied = [];
  const stmts = [];
  for (const op of ops) {
    if (!op || typeof op !== 'object') continue;
    if (op.type === 'add') {
      const s = cleanSale(op.sale);
      if (s) {
        // 同じ会計が二重に届いても 1 件だけ残す（電波が悪いときの再送対策）
        stmts.push(db.prepare(
          `INSERT OR IGNORE INTO sales (id, ts, day, normal, normal_ice, ticket, ticket_ice, cups, ice, total,
            received, change, drink_price, ice_price, voided, voided_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, NULL)`
        ).bind(s.id, s.ts, s.day, s.items.normal, s.items.normalIce, s.items.ticket, s.items.ticketIce,
          s.cups, s.ice, s.total, s.received, s.change, s.drink, s.icePrice));
      }
    } else if (op.type === 'void') {
      const voided = op.voided ? 1 : 0;
      stmts.push(db.prepare('UPDATE sales SET voided = ?, voided_at = ? WHERE id = ?')
        .bind(voided, voided ? Math.floor(num(op.at, Date.now())) : null, String(op.id || '')));
    }
    // 不正な操作も「処理済み」にして、端末の送信待ちに残り続けないようにする
    applied.push(String(op.opId || ''));
  }
  if (stmts.length) {
    stmts.push(db.prepare(
      `INSERT INTO meta (k, v) VALUES ('version', '1')
       ON CONFLICT(k) DO UPDATE SET v = CAST(CAST(v AS INTEGER) + 1 AS TEXT)`));
    await db.batch(stmts);
  }
  const version = (await getMeta(db, 'version')) || '0';
  const res = { ok: true, applied, version };
  if (version !== body.version) {
    const { results } = await db.prepare('SELECT * FROM sales ORDER BY ts DESC').all();
    res.sales = results.map(rowToSale);
  }
  return json(res);
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (request.method === 'GET' && (url.pathname === '/' || url.pathname === '/index.html')) {
      return new Response(PAGE_HTML, {
        headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-cache' }
      });
    }
    if (url.pathname.startsWith('/api/')) {
      if (request.method !== 'POST') return json({ ok: false, error: 'method' }, 405);
      if (!env.DB) return json({ ok: false, error: 'no_database' }, 500);
      let body = {};
      try { body = await request.json(); } catch (e) { return json({ ok: false, error: 'bad_json' }, 400); }
      await ensureSchema(env.DB);
      if (url.pathname === '/api/login') return apiLogin(body, env);
      if (url.pathname === '/api/sync') return apiSync(body, env);
    }
    return new Response('Not found', { status: 404 });
  }
};
